// Job detail page (generated by scripts/build-jobs.mjs): sticky facts / bottom bar, share link,
// inline application form (validation on blur, draft on this device, CV upload, confirmation in place).
import { initSite, gsap, ScrollTrigger, reduceMotion, toast, lenis } from '../../ds/site.js';
import { autoMount3D } from '../../ds/fx3d.js';
import { validateApplication, LIMITS } from '../../lib/application-validation.js';
import { $, $$, splitHeadings, magnetic, tilt, refreshPosted } from '../careers/motion.js';
import { createCvUpload, fileToBase64 } from '../careers/cv-upload.js';
import { setFieldError, formValues, lockForm, postJson, sendErrorText } from '../careers/form-utils.js';
import './job.css';

initSite();
autoMount3D();
magnetic();
tilt('[data-tilt]', 4);
refreshPosted();

const JOB = JSON.parse($('main').dataset.job);
const DRAFT_KEY = `savvy-apply-draft:${JOB.slug}`;
const APPLIED_KEY = `savvy-applied:${JOB.slug}`;
const store = {
  get: (k) => {
    try {
      return JSON.parse(localStorage.getItem(k) || 'null');
    } catch {
      return null;
    }
  },
  set: (k, v) => {
    try {
      localStorage.setItem(k, JSON.stringify(v));
      return true;
    } catch {
      return false;
    }
  },
  del: (k) => {
    try {
      localStorage.removeItem(k);
    } catch {
      /* storage unavailable */
    }
  },
};
const scrollToEl = (el, offset = -120) => {
  const top = Math.max(0, el.getBoundingClientRect().top + scrollY + offset);
  if (lenis) {
    lenis.resize();
    lenis.scrollTo(top, { duration: reduceMotion ? 0 : 1, force: true });
  } else scrollTo({ top, behavior: reduceMotion ? 'auto' : 'smooth' });
};
const shortDate = (d) => new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

// ---------------------------------------------------------------------------
// Motion: title reveal, hiring-process line drawn with scroll
// ---------------------------------------------------------------------------
const mm = gsap.matchMedia();
mm.add('(prefers-reduced-motion: no-preference)', () => {
  splitHeadings();
  const proc = $('[data-process]');
  if (proc)
    ScrollTrigger.create({
      trigger: proc,
      start: 'top 80%',
      end: 'bottom 55%',
      scrub: true,
      onUpdate: (s) => proc.style.setProperty('--p', s.progress.toFixed(3)),
    });
  gsap.from('[data-process] li', { opacity: 0, y: 16, duration: 0.7, stagger: 0.08, ease: 'expo.out', scrollTrigger: { trigger: '[data-process]', start: 'top 85%' } });
});

// ---------------------------------------------------------------------------
// Share / copy link → toast
// ---------------------------------------------------------------------------
async function copyLink() {
  const url = `${location.origin}${location.pathname}`;
  try {
    await navigator.clipboard.writeText(url);
  } catch {
    const ta = Object.assign(document.createElement('textarea'), { value: url });
    ta.setAttribute('readonly', '');
    ta.style.cssText = 'position:fixed;opacity:0';
    document.body.append(ta);
    ta.select();
    document.execCommand('copy');
    ta.remove();
  }
  toast({ title: 'Link copied', message: `Share the ${JOB.title} role with anyone.`, type: 'success', duration: 3000 });
}
$$('[data-share]').forEach((b) => b.addEventListener('click', copyLink));

// ---------------------------------------------------------------------------
// Mobile bottom bar: visible once the title scrolled away, hidden while the form is on screen
// ---------------------------------------------------------------------------
const bar = $('[data-job-bar]');
let pastTop = false;
let atForm = false;
const syncBar = () => {
  const on = pastTop && !atForm;
  bar.classList.toggle('is-visible', on);
  bar.setAttribute('aria-hidden', String(!on));
  $$('a, button', bar).forEach((el) => (el.tabIndex = on ? 0 : -1));
};
const topEl = $('[data-job-top]');
const applyEl = $('#apply');
const fromRects = () => {
  pastTop = topEl.getBoundingClientRect().bottom < 0;
  const r = applyEl.getBoundingClientRect();
  atForm = r.top < innerHeight && r.bottom > 0;
  syncBar();
};
ScrollTrigger.create({ start: 0, end: 'max', onUpdate: fromRects });
addEventListener('resize', fromRects);
fromRects();

// ===========================================================================
// Application form
// ===========================================================================
const form = $('[data-apply-form]');
const done = $('[data-apply-done]');
const draftStatus = $('[data-draft-status]');
const bannerDraft = $('[data-banner-draft]');
const bannerErrors = $('[data-banner-errors]');
const bannerNet = $('[data-banner-network]');
const submitLabel = $('[data-submit-label]', form);
const whyCount = $('[data-why-count]');
const FIELDS = ['name', 'email', 'phone', 'location', 'workAuth', 'cv', 'linkedin', 'portfolio', 'why', 'experience', ...(JOB.requiresOverlap ? ['overlap'] : []), 'salary', 'heardFrom', 'consent'];
const LABELS = { name: 'Full name', email: 'Email', phone: 'Phone', location: 'Location / time zone', workAuth: 'Work authorization', cv: 'CV / résumé', linkedin: 'LinkedIn profile', portfolio: 'Portfolio or website', why: 'Why Savvy Post?', experience: 'Experience', overlap: 'US hours overlap', salary: 'Salary expectation', heardFrom: 'How did you hear about us?', consent: 'Data consent' };
const touched = new Set();
let failures = 0;

const cv = createCvUpload($('[data-field="cv"]', form), {
  setError: (msg) => {
    touched.add('cv');
    setFieldError(form, 'cv', msg);
  },
  onChange: (file) => file && setFieldError(form, 'cv', ''),
});

function validate() {
  const { values, errors } = validateApplication(formValues(form), { kind: 'role', requiresOverlap: JOB.requiresOverlap });
  const cvErr = cv.validate();
  if (cvErr) errors.cv = cvErr;
  return { values, errors };
}
const showErrors = (errors, only) => FIELDS.forEach((k) => (only ? only.includes(k) : true) && setFieldError(form, k, errors[k] || ''));

// Validate on blur (first time), then live while the field shows an error
form.addEventListener('focusout', (e) => {
  const name = e.target.name;
  if (!FIELDS.includes(name) || name === 'cv') return;
  if (name === 'overlap' && form.contains(e.relatedTarget) && e.relatedTarget?.name === 'overlap') return;
  touched.add(name);
  showErrors(validate().errors, [name]);
});
form.addEventListener('input', (e) => {
  const name = e.target.name;
  if (name === 'why') {
    const n = e.target.value.length;
    whyCount.textContent = n;
    whyCount.parentElement.classList.toggle('is-over', n > LIMITS.why);
  }
  if (touched.has(name) && $(`[data-field="${name}"]`, form)?.classList.contains('has-error')) showErrors(validate().errors, [name]);
  saveDraftSoon();
});
form.addEventListener('change', (e) => {
  if (e.target.type === 'checkbox' || e.target.type === 'radio' || e.target.tagName === 'SELECT') {
    touched.add(e.target.name);
    showErrors(validate().errors, [e.target.name]);
  }
  saveDraftSoon();
});

// ---------------------------------------------------------------------------
// Draft on this device (the CV file is never stored)
// ---------------------------------------------------------------------------
let draftTimer;
function saveDraftSoon() {
  clearTimeout(draftTimer);
  draftTimer = setTimeout(() => {
    const values = formValues(form);
    delete values.botField;
    if (store.set(DRAFT_KEY, { savedAt: Date.now(), values })) draftStatus.textContent = '● Draft saved on this device';
  }, 800);
}
function restoreDraft() {
  const draft = store.get(DRAFT_KEY);
  if (!draft?.values) return;
  if (Date.now() - draft.savedAt > 30 * 86400000) return store.del(DRAFT_KEY); // drafts expire after 30 days
  const hasContent = Object.entries(draft.values).some(([k, v]) => k !== 'keepOnFile' && v);
  if (!hasContent) return;
  for (const [k, v] of Object.entries(draft.values)) {
    const el = form.elements[k];
    if (!el) continue;
    if (el instanceof RadioNodeList) [...el].forEach((r) => (r.checked = r.value === v));
    else if (el.type === 'checkbox') el.checked = Boolean(v);
    else el.value = v;
  }
  whyCount.textContent = form.elements.why.value.length;
  $('[data-draft-when]', bannerDraft).textContent = `Welcome back. We restored your draft from ${shortDate(draft.savedAt)}.`;
  bannerDraft.hidden = false;
  draftStatus.textContent = '● Draft saved on this device';
}
$('[data-draft-clear]').addEventListener('click', () => {
  if (!confirm('Start over? This clears the answers saved on this device.')) return;
  store.del(DRAFT_KEY);
  form.reset();
  cv.clear();
  whyCount.textContent = '0';
  touched.clear();
  showErrors({});
  bannerDraft.hidden = true;
  draftStatus.textContent = '';
  form.elements.name.focus();
});

// ---------------------------------------------------------------------------
// Submit
// ---------------------------------------------------------------------------
function errorSummary(errors) {
  const keys = FIELDS.filter((k) => errors[k]);
  $('[data-errors-title]', bannerErrors).textContent = `${keys.length} field${keys.length > 1 ? 's need' : ' needs'} your attention`;
  const ul = $('[data-errors-list]', bannerErrors);
  ul.innerHTML = '';
  keys.forEach((k) => {
    const li = document.createElement('li');
    const a = document.createElement('a');
    const target = k === 'overlap' ? form.querySelector('[name="overlap"]') : form.querySelector(`#f-${k}`);
    a.href = `#${target?.id || `f-${k}`}`;
    a.textContent = `${LABELS[k]}: ${errors[k]}`;
    a.addEventListener('click', (e) => {
      e.preventDefault();
      target?.focus();
      if (target) scrollToEl(target, -200);
    });
    li.append(a);
    ul.append(li);
  });
  bannerErrors.hidden = false;
  bannerErrors.focus();
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  bannerNet.hidden = true;
  bannerErrors.hidden = true;
  FIELDS.forEach((k) => touched.add(k));
  const { values, errors } = validate();
  showErrors(errors);
  if (Object.keys(errors).length) return errorSummary(errors);

  const file = cv.file;
  submitLabel.textContent = 'Uploading your CV…';
  lockForm(form, true);
  const slow = setTimeout(() => (submitLabel.textContent = 'Still working, don’t close this page'), 10000);
  let r;
  try {
    const data = await fileToBase64(file);
    submitLabel.textContent = 'Sending…';
    r = await postJson('/api/apply', { kind: 'role', role: JOB.slug, ...formValues(form), consent: true, botField: form.elements.botField.value, cv: { name: file.name, size: file.size, type: file.type, data } });
  } catch {
    r = { ok: false, status: 0, error: 'read' };
  }
  clearTimeout(slow);
  lockForm(form, false);
  submitLabel.textContent = 'Submit application';

  if (r.ok) {
    const record = { name: values.name, email: values.email, at: Date.now(), ref: r.ref || '—', cv: file.name };
    store.set(APPLIED_KEY, record);
    store.del(DRAFT_KEY);
    showConfirmation(record, true);
    return;
  }
  if (r.error === 'validation' && r.fields) {
    showErrors(r.fields);
    return errorSummary(r.fields);
  }
  failures++;
  const ref = `${r.status || 'NET'}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
  $('[data-network-text]', bannerNet).textContent = sendErrorText(r);
  $('[data-network-ref]', bannerNet).textContent = `ref ${ref}`;
  const mail = $('[data-mailto]', bannerNet);
  if (failures >= 2) {
    const body = `Role: ${JOB.title}\nName: ${values.name}\nEmail: ${values.email}\nLinkedIn: ${values.linkedin}\n\n${values.why}\n\n(Please attach your CV.)\nref ${ref}`;
    mail.href = `mailto:${JOB.email}?subject=${encodeURIComponent(`Application: ${JOB.title} — ${values.name}`)}&body=${encodeURIComponent(body)}`;
    mail.hidden = false;
  }
  bannerNet.hidden = false;
  bannerNet.focus();
});

// ---------------------------------------------------------------------------
// Confirmation (replaces the form in place; #applied keeps it after a refresh)
// ---------------------------------------------------------------------------
function showConfirmation(rec, animate) {
  $('[data-done-name]', done).textContent = rec.name.split(' ')[0];
  $('[data-done-email]', done).textContent = rec.email;
  $('[data-done-date]', done).textContent = new Date(rec.at).toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });
  $('[data-done-ref]', done).textContent = rec.ref;
  $('[data-done-cv]', done).textContent = rec.cv;
  form.hidden = true;
  done.hidden = false;
  history.replaceState(null, '', `${location.pathname}${location.search}#applied`);
  $$('[data-apply-cta]').forEach((a) => {
    $('span', a).textContent = `Applied ✓ · ${shortDate(rec.at)}`;
    a.setAttribute('aria-disabled', 'true');
    a.removeAttribute('href');
    a.tabIndex = -1;
  });
  $('.job-aside')?.classList.add('is-applied');
  if (animate) {
    const title = $('[data-done-title]', done);
    scrollToEl($('#apply'));
    title.focus({ preventScroll: true });
    if (!reduceMotion) gsap.from(done.children, { opacity: 0, y: 20, duration: 0.7, stagger: 0.1, ease: 'expo.out' });
  }
  ScrollTrigger.refresh();
}

const applied = store.get(APPLIED_KEY);
if (location.hash === '#applied' && applied) showConfirmation(applied, false);
else restoreDraft();
